css:
@page { size: A4 portrait; margin: 12mm; }

.print-format {
    font-family: Arial, sans-serif;
    font-size: 12px;
    color: #222;
    padding: 0;
}

.body {
    margin-left: 15mm;
    margin-right: 15mm;
}

.detail-row { display: table; width: 100%; margin: 2px 0; }
.detail-row > div { display: table-cell; width: 50%; vertical-align: top; }

.section-title {
    font-weight: bold;
    font-size: 12px;
    margin: 14px 0 6px 0;
    border-bottom: 1px solid #666;
    padding-bottom: 2px;
}

.intro {
    white-space: pre-wrap;
    padding: 6px 8px;
}

.attendees { width: 100%; border-collapse: collapse; }
.attendees th, .attendees td {
    border: 1px solid #333;
    padding: 6px 8px;
    text-align: left;
    font-size: 12px;
}
.attendees thead th { background: #e8e8e8; font-weight: bold; }
.attendees .idx { width: 30px; text-align: center; }
.attendees .sig { width: 140px; }
.attendees tbody tr { page-break-inside: avoid; }
